const app = express();

// Validate environment variables
if (!process.env.PORT) {
  console.warn('PORT environment variable not set, using default 3000');
}

// Health endpoint
app.get('/health', (req, res) => {
  const healthCheck = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    service: 'user-api'
  };
  res.status(200).json(healthCheck);
});

// Users endpoint
