// Environment configuration validation utility

/**
 * Validates required environment variables
 * @param {string[]} requiredVars - Array of required variable names
 * @returns {object} - Object with success status and messages
 */
function validateEnvironment(requiredVars) {
  const errors = [];
  const missing = [];

  requiredVars.forEach((varName) => {
    if (!process.env[varName]) {
      missing.push(varName);
    }
  });

  if (missing.length > 0) {
    errors.push(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Check for common misconfigurations
  if (process.env.NODE_ENV && !['development', 'test', 'production'].includes(process.env.NODE_ENV)) {
    errors.push(`Invalid NODE_ENV: "${process.env.NODE_ENV}". Must be development, test, or production.`);
  }

  return {
    valid: errors.length === 0,
    errors: errors,
    missing: missing
  };
}

/**
 * Validates port configuration
 * @param {number|string} port - Port to validate
 * @returns {boolean} - True if port is valid
 */
function validatePort(port) {
  if (!port) return false;

  const portNumber = parseInt(port);
  return portNumber && portNumber >= 0 && portNumber <= 65535;
}

/**
 * Parses and validates numeric environment variables
 * @param {string} varName - Variable name
 * @param {number} defaultValue - Default value if missing
 * @param {number} min - Minimum allowed value
 * @param {number} max - Maximum allowed value
 * @returns {number} - Validated number
 */
function getValidatedNumber(varName, defaultValue, min = 0, max = Number.MAX_VALUE) {
  if (process.env[varName]) {
    const parsed = parseInt(process.env[varName]);
    if (isNaN(parsed)) {
      console.error(`Invalid ${varName}: "${process.env[varName]}". Must be a number. Using default: ${defaultValue}`);
      return defaultValue;
    }
    if (parsed < min || parsed > max) {
      console.error(`Invalid ${varName}: "${parsed}". Must be between ${min} and ${max}. Using default: ${defaultValue}`);
      return defaultValue;
    }
    return parsed;
  }
  return defaultValue;
}

// Export the functions
module.exports = {
  validateEnvironment,
  validatePort,
  getValidatedNumber
};

