// Secure version of app.js with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// Security middleware
app.use(helmet());
app.use(cors({ origin: 'https://yourdomain.com' })); // Restrict CORS to trusted origins

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
});
app.use(limiter);

// Logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Health endpoint
app.get('/health', (req, res) => {
  logger.info('Health check accessed');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint with authentication check (mock example)
const authenticate = (req, res, next) => {
  // Example: Check for a valid API key or auth header
  const apiKey = req.headers['x-api-key'];
  if (apiKey === process.env.API_KEY) {
    next();
  } else {
    logger.warn('Unauthorized access attempt to /users');
    res.status(401).json({ error: 'Unauthorized' });
  }
};

app.get('/users', authenticate, (req, res) => {
  // Example: Redact sensitive information
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`);
  res.status(500).json({ error: 'Internal Server Error' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
  logger.info('Server started');
});

module.exports = app;

